    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address receiver, uint amount) public payable {
        // Fund this test contract so it can attempt the transfer.
        // The test contract is the owner of c (it deployed c).
        require(address(this).balance >= amount);

        uint beforeBal = address(c).balance;
        uint beforeThis = address(this).balance;

        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // If the test contract has enough Ether, sendTo must succeed and move exactly amount
        // from c to receiver, and c's balance must decrease by exactly amount.
        // If not, the call must revert, c's balance must stay unchanged, and no Ether may move.
